function moverJugador(jugador, direccion, velocidad, limites) {
  // Calculá la nueva posición sin salir del escenario.
  return { x: jugador.x, y: jugador.y };
}

challenges.solutionCode:
function moverJugador(jugador, direccion, velocidad, limites) {
  return {
    x: Math.max(0, Math.min(limites.ancho, jugador.x + direccion.x * velocidad)),
    y: Math.max(0, Math.min(limites.alto, jugador.y + direccion.y * velocidad))
  };
}

