challenges.solutionCode:
function aplicarEvento(estado, evento) {
  const nuevo = { ...estado };
  if (evento.tipo === 'gema') nuevo.puntos += 10;
  else if (evento.tipo === 'gema-especial') {
    nuevo.puntos += 25;
    nuevo.combo += 1;
  } else if (evento.tipo === 'daño') {
    nuevo.vidas = Math.max(0, nuevo.vidas - 1);
    nuevo.combo = 0;
  }
  return nuevo;
}

