challenges.solutionCode:
function crearOleada(nivel, ancho) {
  const cantidad = Math.max(0, Math.floor(nivel)) + 2;
  const enemigos = [];
  for (let i = 0; i < cantidad; i++) {
    enemigos.push({
      x: ancho * (i + 1) / (cantidad + 1),
      velocidad: i + 1
    });
  }
  return enemigos;
}
